Query:
SELECT ?correction ?type
WHERE {
    {
        ?correction a :PositiveCorrection .
        BIND("Positive" AS ?type)
    }
    UNION
    {
        ?correction a :NegativeCorrection .
        BIND("Negative" AS ?type)
    }
}

SELECT DISTINCT ?scan ?pitfall given_ontology
WHERE {
    ?scan a :Scan ;
          :contains ?pitfall ;
          :evaluates given_ontology .

    given_ontology a :Ontology .
    ?pitfall a :Pitfall .
}
